# ==================================================
# EMERGENCY AGENT
#
# Fixed, pre-written responses -- deliberately NOT generated by an LLM.
# An emergency reply must be instant, identical every time, and work even
# if the LLM provider is down.
#
# Numbers (India), checked against official / government-reported sources:
#   112   national emergency number (police, fire, ambulance)
#   108   emergency ambulance, available in most states
#   102   ambulance for pregnant women and newborns
#   14416 / 1800-891-4416   Tele-MANAS, free 24x7 mental-health helpline
#         run under the Ministry of Health and Family Welfare
# India is merging its older emergency lines into 112, so 112 always comes
# first and 108 is described as "in most states".
# ==================================================

from typing import Optional

from app.utils.emergency_detector import EmergencyAssessment
from app.utils.messages import tr

CALL_NOW = (
    "This could be a medical emergency. Please call 112 (India's national "
    "emergency number) right now, or 108 for an ambulance in most states. "
    "If someone is with you, ask them to stay with you and help. Don't wait "
    "to see if it passes, and avoid driving yourself."
)

FIRST_AID = {
    "CARDIAC": (
        "While you wait: sit down, stay as still and calm as you can, and "
        "loosen tight clothing. Don't take any medicine unless the emergency "
        "operator tells you to."
    ),
    "BREATHING": (
        "While you wait: sit upright, loosen tight clothing, and try to stay "
        "as calm as you can. If you have a prescribed rescue inhaler, use it "
        "as directed."
    ),
    "STROKE": (
        "While you wait: note the exact time the symptoms began and tell the "
        "responders. Don't give food, drink or medicine by mouth."
    ),
    "EYE": (
        "While you wait: don't rub or press on the eye and don't put in any "
        "drops or ointment unless a doctor tells you to. If a chemical got "
        "in the eye, rinse it with clean running water continuously until "
        "help arrives. Ask to be taken to the nearest hospital with an eye "
        "emergency (casualty) service."
    ),
    "BLEEDING": (
        "While you wait: press firmly on the wound with a clean cloth and "
        "keep pressing. Don't remove the cloth if it soaks through; add more "
        "on top. Lie down and raise the injured limb if you can."
    ),
    "CONSCIOUSNESS": (
        "While you wait: check whether the person is breathing. If they are, "
        "lay them on their side. Don't give food or drink. If they are not "
        "breathing, tell the operator straight away; they can guide you "
        "through CPR."
    ),
    "SEIZURE": (
        "While you wait: move hard or sharp objects away, cushion the head, "
        "and turn the person onto their side once the shaking stops. Don't "
        "put anything in their mouth and don't hold them down. Note how long "
        "it lasts."
    ),
    "CHOKING": (
        "If the person can't cough, speak or breathe, tell the emergency "
        "operator now; they can guide you through back blows and abdominal "
        "thrusts. If they can still cough, encourage them to keep coughing."
    ),
    "POISONING": (
        "While you wait: keep the container, packet or pills so the "
        "responders can see what was taken and how much. Don't try to make "
        "the person vomit unless a medical professional tells you to."
    ),
    "ALLERGIC": (
        "While you wait: if you have a prescribed adrenaline (epinephrine) "
        "auto-injector, use it now as directed. Sit or lie down; don't stand "
        "or walk around."
    ),
    "GENERAL": "",
}

SELF_HARM_TEXT = (
    "I'm really sorry you're going through this, and I'm glad you told me. "
    "You deserve support right now.\n\n"
    "If you might act on these thoughts, or you are in immediate danger, "
    "please call 112 now. If you can, move away from anything you could use "
    "to hurt yourself and go to be near another person.\n\n"
    "You can also talk to someone right now, free and 24x7: Tele-MANAS, "
    "India's government mental-health helpline, on 14416 or 1800-891-4416. "
    "Counsellors are available in many languages.\n\n"
    "If there's someone you trust, a family member or friend, please tell "
    "them how you're feeling and ask them to stay with you. You don't have "
    "to handle this alone. I'm an AI assistant, so I can't replace a person "
    "who can be there with you, but I'm here to keep talking."
)

DISCLAIMER = (
    "I'm an AI assistant and can't examine you, so please get in-person "
    "emergency care."
)


_LOCALIZED = ("hi", "mr", "hinglish")


def _build_localized_text(assessment: Optional[EmergencyAssessment], lang: str) -> str:
    """
    Emergency text in Hindi / Marathi / Hinglish. Fixed wording, no LLM.
    The detailed English first-aid lines are replaced by short, general
    instructions (and an eye-specific line for eye emergencies) so the whole
    message stays in one language. Wording is NOT clinician-reviewed.
    """

    if assessment is not None and assessment.categories == ["SELF_HARM"]:
        return tr("self_harm", lang)

    parts = [tr("emergency_call", lang)]

    if assessment is not None and assessment.primary_category == "EYE":
        parts.append(tr("emergency_eye", lang))
    else:
        parts.append(tr("emergency_wait", lang))

    if assessment is not None and assessment.has_self_harm:
        parts.append(tr("self_harm", lang))
    else:
        parts.append(tr("emergency_disclaimer", lang))

    return "\n\n".join(parts)


def build_emergency_text(
    assessment: Optional[EmergencyAssessment],
    lang: Optional[str] = "en"
) -> str:

    if lang in _LOCALIZED:
        return _build_localized_text(assessment, lang)

    if assessment is None:
        return CALL_NOW + "\n\n" + DISCLAIMER

    primary = assessment.primary_category

    # Self-harm only: the supportive message, not an ambulance script.
    if assessment.categories == ["SELF_HARM"]:
        return SELF_HARM_TEXT

    parts = [CALL_NOW]

    first_aid = FIRST_AID.get(primary, "")
    if first_aid:
        parts.append(first_aid)

    # e.g. an overdose that may be intentional: give both messages.
    if assessment.has_self_harm:
        parts.append(SELF_HARM_TEXT)
    else:
        parts.append(DISCLAIMER)

    return "\n\n".join(parts)


def run_emergency_agent(
    message: str,
    assessment: Optional[EmergencyAssessment] = None,
    lang: Optional[str] = "en"
):

    return {
        "response": build_emergency_text(assessment, lang),
        "urgency_tier": "emergency",
        "agent": "EMERGENCY_AGENT",
        "rag_used": False,
        "sources": [],
    }
